// Authored place-specific conversations. Catalogue IDs are append-only.
static const u8 sPipLiving_LITTLEROOT_TOWN_0[] = _("PIP: Your mother asked us to be\ncareful. I am including you in that\lassignment.$");
static const u8 sPipLiving_LITTLEROOT_TOWN_1[] = _("PIP: Coming home is different from\nturning back. We can do either.$");
static const u8 sPipLiving_OLDALE_TOWN_0[] = _("PIP: A person can get directions here\nwithout being made to feel lost. That\lis a good town.$");
static const u8 sPipLiving_OLDALE_TOWN_1[] = _("PIP: I used to think adventures\nstarted with speeches. Ours mostly\lneeded shoes.$");
static const u8 sPipLiving_PETALBURG_CITY_0[] = _("PIP: Do you practice what to say\nbefore visiting your dad? We can take\lanother lap.$");
static const u8 sPipLiving_PETALBURG_CITY_1[] = _("PIP: WALLY was nervous when he\nstarted. Nervous people still get to\lstart.$");
static const u8 sPipLiving_RUSTBORO_CITY_0[] = _("PIP: That building is older than every\nworry I have. Most of the worries are\labout lunch.$");
static const u8 sPipLiving_RUSTBORO_CITY_1[] = _("PIP: The students are learning type\nmatchups. I am learning that school\lbells still frighten me.$");
static const u8 sPipLiving_DEWFORD_TOWN_0[] = _("PIP: Somebody here made a very small\nboat their whole job. I respect a\lclear plan.$");
static const u8 sPipLiving_DEWFORD_TOWN_1[] = _("PIP: We could sit by the sea until the\ntrend changes. I am prepared to\lcontribute.$");
static const u8 sPipLiving_SLATEPORT_CITY_0[] = _("PIP: The market smells like lunch and\nfinancial decisions. A dangerous\lcombination.$");
static const u8 sPipLiving_SLATEPORT_CITY_1[] = _("PIP: Every ship here came from\nsomewhere. I keep wondering what it\lbrought besides cargo.$");
static const u8 sPipLiving_MAUVILLE_CITY_0[] = _("PIP: Everyone is meeting someone at\nthis crossroads. I am glad I already\lfound you.$");
static const u8 sPipLiving_MAUVILLE_CITY_1[] = _("PIP: I tried counting bicycles. The\nbicycles kept leaving. Poor study\ldesign.$");
static const u8 sPipLiving_VERDANTURF_TOWN_0[] = _("PIP: It is easier to hear yourself\nthink here. Unfortunately, I can also\lhear myself being hungry.$");
static const u8 sPipLiving_VERDANTURF_TOWN_1[] = _("PIP: If WALLY needs a quiet\nafternoon, this place has clearly\lsaved him several.$");
static const u8 sPipLiving_FALLARBOR_TOWN_0[] = _("PIP: They sweep the ash and it comes\nback. Looking after a place is not\lalways about winning.$");
static const u8 sPipLiving_FALLARBOR_TOWN_1[] = _("PIP: I put a little ash in my pocket. I\nwas going to do that accidentally\lanyway.$");
static const u8 sPipLiving_LAVARIDGE_TOWN_0[] = _("PIP: My shoulders have stopped\npretending to be armor. The hot\lspring is doing good work.$");
static const u8 sPipLiving_LAVARIDGE_TOWN_1[] = _("PIP: The old trainers here have\nexcellent stories. I wonder which\lpart they used to be nervous about.$");
static const u8 sPipLiving_FORTREE_CITY_0[] = _("PIP: Someone had to carry the first\nchair up here. History overlooks its\lgreatest workers.$");
static const u8 sPipLiving_FORTREE_CITY_1[] = _("PIP: The houses move a little with the\nbranches. The trees are very patient\lroommates.$");
static const u8 sPipLiving_LILYCOVE_CITY_0[] = _("PIP: A picture in the museum made me\nstop walking. I think that means it\lworked.$");
static const u8 sPipLiving_LILYCOVE_CITY_1[] = _("PIP: We can look in the shop without\nbuying anything. I have prepared a\lbrave face.$");
static const u8 sPipLiving_MOSSDEEP_CITY_0[] = _("PIP: They are sending things into\nspace. I still congratulate myself\lfor finding the correct door.$");
static const u8 sPipLiving_MOSSDEEP_CITY_1[] = _("PIP: Those twins must know what the\nother is thinking. I hope they use\lthat power to order lunch.$");
static const u8 sPipLiving_SOOTOPOLIS_CITY_0[] = _("PIP: The steps make everyone slow\ndown. Even a dramatic arrival needs\lto catch its breath.$");
static const u8 sPipLiving_SOOTOPOLIS_CITY_1[] = _("PIP: There are people living here\nafter everything that happened.\lOrdinary mornings can be quite brave.$");
static const u8 sPipLiving_PACIFIDLOG_TOWN_0[] = _("PIP: I can hear water under the floor.\nThis town has committed to the sound\lof being on holiday.$");
static const u8 sPipLiving_PACIFIDLOG_TOWN_1[] = _("PIP: A house here is a little promise\nthat the next tide will be\lmanageable.$");
static const u8 sPipLiving_EVER_GRANDE_CITY_0[] = _("PIP: Before we go in: I am glad I came.\nThat is the whole speech.$");
static const u8 sPipLiving_EVER_GRANDE_CITY_1[] = _("PIP: You do not have to win to justify\ncoming this far with me.$");
static const u8 sPipWatch_PALLET_TOWN_0[] = _("PIP: A completely different world.\nSame shoes. I expected paperwork.$");
static const u8 sPipWatch_PALLET_TOWN_1[] = _("PIP: If we meet another me, please\nask which of us packed lunch.$");
static const u8 sPipWatch_ROUTE_1_0[] = _("PIP: New world, familiar tall grass.\nSome things are very committed.$");
static const u8 sPipWatch_ROUTE_1_1[] = _("PIP: That ledge only goes one way.\nThe watch has better manners.$");
static const u8 sPipWatch_VIRIDIAN_CITY_0[] = _("PIP: The PC still knows our boxes.\nI hope it does not charge roaming.$");
static const u8 sPipWatch_VIRIDIAN_CITY_1[] = _("PIP: We can go home whenever you like.\nI like knowing that.$");

